shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/tokio/tests/sync_broadcast.rs
+++ b/tokio/tests/sync_broadcast.rs
@@ -504,6 +504,49 @@
 }

 #[test]
+fn resubscribe_closed() {
+    for capacity in [1, 2, 4] {
+        for messages in [0, capacity, capacity + 1] {
+            let (tx, rx) = broadcast::channel(capacity);
+            for value in 0..messages {
+                assert_ok!(tx.send(value));
+            }
+            drop(tx);
+
+            let mut rx_resub = rx.resubscribe();
+            assert!(is_closed(assert_ready_err!(
+                task::spawn(rx_resub.recv()).poll()
+            )));
+            assert_closed!(rx_resub.try_recv());
+
+            drop(rx);
+
+            assert!(is_closed(assert_ready_err!(
+                task::spawn(rx_resub.recv()).poll()
+            )));
+            assert_closed!(rx_resub.try_recv());
+
+            let mut rx_resub = rx_resub.resubscribe();
+            assert_closed!(rx_resub.try_recv());
+        }
+    }
+}
+
+#[test]
+fn resubscribe_after_receiving_closed() {
+    let (tx, mut rx) = broadcast::channel::<()>(4);
+    drop(tx);
+    assert_closed!(rx.try_recv());
+
+    let mut rx_resub = rx.resubscribe();
+    assert_closed!(rx_resub.try_recv());
+    assert!(is_closed(assert_ready_err!(
+        task::spawn(rx_resub.recv()).poll()
+    )));
+    assert_closed!(rx.try_recv());
+}
+
+#[test]
 fn resubscribe_lagged() {
     let (tx, mut rx) = broadcast::channel(1);
     tx.send(1).unwrap();
PATCH
cargo test --offline --test sync_broadcast --features full resubscribe_closed

